// The alias is absolute because vitest rejects relative ones.
export default {
  test: {
    include: [
      'tests/**/*.test.ts',
    ],
    watchExclude: [
      'tmp/**/*',
    ],
    globals: true,
  },
  resolve: {
    alias: {
      gbnf: '/workspace/ported_implementation/src/index.ts',
    },
  },
};

from typing import List

from ..grammar_graph.rule_ref import RuleRef
from ..grammar_graph.type_guards import is_range, is_rule_end
from ..grammar_graph.types import RuleChar, RuleCharExclude, RuleEnd
from ..rules_builder.type_guards import (
    is_rule_def_alt,
    is_rule_def_char,
    is_rule_def_char_alt,
    is_rule_def_char_not,
    is_rule_def_char_rng_upper,
    is_rule_def_end,
    is_rule_def_ref,
)
from ..rules_builder.types import InternalRuleDef


def _make_char_rule(rule_def: InternalRuleDef):
    value = list(rule_def.value)
    return RuleCharExclude(value) if is_rule_def_char_not(rule_def) else RuleChar(value)


def build_rule_stack(linear_rules: List[InternalRuleDef]) -> List[List[object]]:
    paths: List[object] = []

    stack: List[List[object]] = []

    idx = 0
    while idx < len(linear_rules):
        rule_def = linear_rules[idx]
        if is_rule_def_char(rule_def) or is_rule_def_char_not(rule_def):
            # this could be a single char, or a range, or a sequence of alts;
            # we don't know until we step through it.
            char_rule = _make_char_rule(rule_def)
            idx += 1
            rule = linear_rules[idx] if idx < len(linear_rules) else None
            while idx < len(linear_rules) and (
                is_rule_def_char_rng_upper(rule) or is_rule_def_char_alt(rule)
            ):
                if is_rule_def_char_rng_upper(rule):
                    # previous rule value should be a number
                    if not char_rule.value:
                        raise Exception("Unexpected undefined value")
                    prev_value = char_rule.value.pop()
                    if is_range(prev_value):
                        raise Exception(
                            "Unexpected range, expected a number but got an array: "
                            f"{prev_value!r}"
                        )
                    char_rule.value.append([prev_value, rule.value])
                if is_rule_def_char_alt(rule):
                    char_rule.value.append(rule.value)
                idx += 1
                rule = linear_rules[idx] if idx < len(linear_rules) else None
            paths.append(char_rule)
        else:
            if is_rule_def_alt(rule_def):
                if not paths:
                    raise Exception("Encountered alt without anything before it")
                paths.append(RuleEnd())
                stack.append(paths)
                paths = []
            elif is_rule_def_end(rule_def):
                paths.append(RuleEnd())
            elif is_rule_def_ref(rule_def):
                paths.append(RuleRef(rule_def.value))
            elif is_rule_def_char_alt(rule_def):
                raise Exception(
                    f"Encountered char alt, should be handled by above block: {rule_def.type}"
                )
            else:
                raise Exception(f"Unsupported rule type: {rule_def.type}")
            idx += 1

    if not (paths and is_rule_end(paths[-1])):
        paths.append(RuleEnd())

    stack.append(paths)

    return stack

import { describe, test, expect } from 'vitest';
import GBNF, { RuleType } from 'gbnf';

describe('Iteration', () => {
  test.for([
    ['root ::= "foo"', [{ type: 'char', value: [102] }]],
    [
      'root ::= "foo" | "bar" ',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    [
      'root ::= "foo" | "bar" | "gaz"',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
        { type: 'char', value: [103] },
      ],
    ],
    [
      'root ::= "foo" | "bar" | "baz"',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    ['root ::= [^x]', [{ type: 'char_exclude', value: [120] }]],
    ['root ::= [^f] "o"', [{ type: 'char_exclude', value: [102] }]],
    ['root ::= [^A-Z]', [{ type: 'char_exclude', value: [[65, 90]] }]],
    [
      'root ::= [^A-Z0-9]',
      [
        {
          type: 'char_exclude',
          value: [
            [65, 90],
            [48, 57],
          ],
        },
      ],
    ],
    [
      'root ::= [^A-Z0-9_-]',
      [{ type: 'char_exclude', value: [[65, 90], [48, 57], 95, 45] }],
    ],
    ['\nroot ::= foo\nfoo ::= "foo"\n  ', [{ type: 'char', value: [102] }]],
    [
      '\nroot ::= f\nf ::= foo\nfoo ::= "foo"\n  ',
      [{ type: 'char', value: [102] }],
    ],
    [
      '\nroot ::= foo | "bar"\nfoo ::= "foo"',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    [
      '\nroot ::= foo | bar\nfoo ::= "foo"\nbar ::= "bar"\n  ',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    [
      '\nroot ::= f | b\nf ::= fo\nb ::= ba\nfo ::= foo\nba ::= bar | baz\nfoo ::= "foo"\nbar ::= "bar"\nbaz ::= "baz"\n  ',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    ['root ::= [a-z]', [{ type: 'char', value: [[97, 122]] }]],
    [
      'root ::= [a-zA-Z]',
      [
        {
          type: 'char',
          value: [
            [97, 122],
            [65, 90],
          ],
        },
      ],
    ],
    [
      'root ::= [a-z]?',
      [{ type: 'char', value: [[97, 122]] }, { type: 'end' }],
    ],
    ['root ::= [a-z]+', [{ type: 'char', value: [[97, 122]] }]],
    [
      'root ::= [a-z]*',
      [{ type: 'char', value: [[97, 122]] }, { type: 'end' }],
    ],
    ['\n  root ::= "foo"\n  foo ::= "foo"', [{ type: 'char', value: [102] }]],
    [
      '\n  root  ::= (expr "=" term "\\n")+\n  expr  ::= term ([-+*/] term)*\n  term  ::= [0-9]+\n  ',
      [{ type: 'char', value: [[48, 57]] }],
    ],
  ] as [string, { type: string; value: number[] }[]][])(
    'It returns parse state for a grammar (%#): `%s`',
    ([grammar, expected]) => {
      let state = GBNF(grammar);
      expect([...state]).toEqual(expected);
    }
  );
});

