mkdir -p /tmp/smoke && cat > /tmp/smoke/smoke.test.ts <<'EOF'
import { describe, test, expect } from 'vitest';
import GBNF, { GBNF as named, GrammarParseError, InputParseError, RuleType, isRange, ParseState } from 'gbnf';

describe('smoke', () => {
  test('no rules / no root', () => {
    expect(() => GBNF('')).toThrowError(new GrammarParseError('', 0, 'No rules were found'));
    expect(() => GBNF('foo ::= "bar"')).toThrowError(
      new GrammarParseError('foo ::= "bar"', 0,
        'Grammar does not contain a root symbol. Available symbols are: ["foo"]')
    );
  });

  test('state surface', () => {
    const state = GBNF('root ::= "foo" | "bar"');
    expect(named).toBe(GBNF);
    expect(state).toBeInstanceOf(ParseState);
    expect(state.size).toBe(2);
    expect(state.grammar).toBe('root ::= "foo" | "bar"');
    expect([...state.rules()]).toEqual([...state]);
    expect(state.add('f').size).toBe(1);
    // states are immutable
    expect([...state]).toHaveLength(2);
    expect(String(state)).toBe('ParseState([{"type":"char","value":[102]},{"type":"char","value":[98]}])');
  });

  test('rule types and isRange', () => {
    expect([...GBNF('root ::= [^a-z]')]).toEqual([{ type: RuleType.CHAR_EXCLUDE, value: [[97, 122]] }]);
    expect(isRange([1, 2])).toBe(true);
    expect(isRange([1, 2, 3])).toBe(false);
    expect(isRange(1)).toBe(false);
  });

  test('escapes and code point input', () => {
    expect([...GBNF('root ::= "\\x41" | "\\u0042" | "\\t" | "\\n" | "\\r" | "\\"" | "\\\\"')]).toEqual([
      { type: 'char', value: [0x41] },
      { type: 'char', value: [0x42] },
      { type: 'char', value: [9] },
      { type: 'char', value: [10] },
      { type: 'char', value: [13] },
      { type: 'char', value: [34] },
      { type: 'char', value: [92] },
    ]);
    // input may be a code point or an array of them
    expect([...GBNF('root ::= "foo"', 102)]).toEqual([{ type: 'char', value: [111] }]);
    expect([...GBNF('root ::= "foo"', [102, 111])]).toEqual([{ type: 'char', value: [111] }]);
  });

  test('comments are skipped', () => {
    expect([...GBNF('# leading comment\nroot ::= "foo" # trailing\n')]).toEqual([
      { type: 'char', value: [102] },
    ]);
  });

  test('errorForMostRecentInput', () => {
    let state = GBNF('root ::= "bar"').add('b').add('a');
    try {
      state.add('z');
      throw new Error('expected a throw');
    } catch (err) {
      expect(err).toBeInstanceOf(InputParseError);
      const e = err as InputParseError;
      expect(e.name).toBe('InputParseError');
      expect(e.src).toBe('baz');
      expect(e.message).toBe('Failed to parse input string:\n\nbaz\n  ^');
      expect(e.errorForMostRecentInput).toBe('Failed to parse input string:\n\nz\n^');
      // an error built from code points reads the same as one built from a string
      expect(new InputParseError([122], 0, [98, 97]).message).toBe(e.message);
    }
  });

  test('grammar parse errors carry position info', () => {
    try {
      GBNF('root ::= foo');
      throw new Error('expected a throw');
    } catch (err) {
      const e = err as GrammarParseError;
      expect(e.name).toBe('GrammarParseError');
      expect(e.grammar).toBe('root ::= foo');
      expect(e.pos).toBe(9);
      expect(e.reason).toBe('Undefined rule identifier "foo"');
      expect(e.message).toBe(
        'Failed to parse grammar: Undefined rule identifier "foo"\n\nroot ::= foo\n         ^'
      );
    }
  });
});
EOF
