import { test, expect } from 'vitest';
import { Graph } from '/workspace/ported_implementation/src/grammar-graph/graph.ts';
import { buildRuleStack } from '/workspace/ported_implementation/src/grammar-parser/build-rule-stack.ts';
import { RulesBuilder } from '/workspace/ported_implementation/src/rules-builder/rules-builder.ts';

test('graph print matches the reference layout', () => {
  const g = 'root ::= "z" ("bar" | "foo") [a-z] [^0-9] \nx ::= root';
  const b = new RulesBuilder(g);
  const graph = new Graph(g, b.rules.map((r) => buildRuleStack(r!)), b.symbolIds.get('root'));
  expect(graph.print()).toBe(
    [
      '',
      '{0,0,0}[z]-> {0,0,1}Ref(1)-> {0,0,2}[az]-> {0,0,3}char_exclude-> {0,0,4}end',
      '{1,0,0}[b]-> {1,0,1}[a]-> {1,0,2}[r]-> {1,0,3}end',
      '{1,1,0}[f]-> {1,1,1}[o]-> {1,1,2}[o]-> {1,1,3}end',
      '{2,0,0}Ref(0)-> {2,0,1}end',
    ].join('\n')
  );
});
EOF
